        "<strong>Dictionary (Easton's).</strong> <strong>HIRELING</strong> a labourer employed on hire for a limited time (Job 7:1; 14:6; Mark 1:20). His wages were paid as soon as his work was over (Leviticus 19:13). In the time of our Lord a day’s wage was a “penny” (q.v.) i.e., a Roman denarius (Matthew 20:1-14). <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
