        "<strong>Dictionary (Easton's).</strong> <strong>SPIDER T</strong> he trust of the hypocrite is compared to the spider’s web or house (Job 8:14). It is said of the wicked by Isaiah that they “weave the spider’s web” (59:5), i.e., their works and designs are, like the spider’s web, vain and useless. The Hebrew word here used is ’akkabish, “a swift weaver.” In Proverbs 30:28 a different Hebrew word (semamith) is used. It is rendered in the Vulgate by stellio, and in the Revised Version by “lizard.” It may, however, represent the spider, of… <em>[Reviewer: condense Easton's entry as needed.]</em>",
