        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>GALL</strong> (1) Hebrews mererah, meaning “bitterness” (Job 16:13); i.e., the bile secreted in the liver. This word is also used of the poison of asps (20:14), and of the vitals, the seat of life (25). (2.) Hebrews rosh. In Deuteronomy 32:33 and Job 20:16 it denotes the poison of serpents. In Hos. 10:4 the Hebrew word is rendered “hemlock.” The original probably denotes some bitter, poisonous plant, most probably the poppy, which grows up quickly, and is therefore coupled with wormwood… <em>[Reviewer: condense Easton's entry as needed.]</em>",
