        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>GRAVING</strong> (1.) Hebrews hatsabh. Job 19:24, rendered “graven,” but generally means hewn stone or wood, in quarry or forest. (2.) Hebrews harush. Jeremiah 17:1, rendered “graven,” and indicates generally artistic work in metal, wood, and stone, effected by fine instruments. (3.) Hebrews haqaq. Ezekiel 4:1, engraving a plan or map, rendered “pourtray;” Job 19:23, “written.” (4.) Hebrews pasal points rather to the sculptor’s or the carver’s art (Isaiah 30:22; 40:19; 41:7; 44:12-15). (5.)… <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
