        "<strong>Dictionary (Easton's).</strong> <strong>MINE T</strong> he process of mining is described in Job 28:1-11. Moses speaks of the mineral wealth of Palestine (Deuteronomy 8:9). Job 28:4 is rightly thus rendered in the Revised Version, “He breaketh open a shaft away from where men sojourn; they are forgotten of the foot [that passeth by]; they hang afar from men, they swing to and fro.” These words illustrate ancient mining operations. <em>[Reviewer: condense Easton's entry as needed.]</em>",
