        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>QUIVER</strong> the sheath for arrows. The Hebrew word (aspah) thus commonly rendered is found in Job 39:23; Psalm 127:5; Isaiah 22:6; 49:2; Jeremiah 5:16; Lamentations 3:13. In Genesis 27:3 this word is the rendering of the Hebrew teli, which is supposed rather to mean a suspended weapon, literally “that which hangs from one”, i.e., is suspended from the shoulder or girdle. <em>[Reviewer: condense Easton's entry as needed.]</em>",
