        "<strong>Dictionary (Easton's).</strong> <strong>THUNDER</strong> often referred to in Scripture (Job 40:9; Psalm 77:18; 104:7). James and John were called by our Lord “sons of thunder” (Mark 3:17). In Job 39:19, instead of “thunder,” as in the Authorized Version, the Revised Version translates (ra’amah) by “quivering main” (marg., “shaking”). Thunder accompanied the giving of the law at Sinai (Exodus 19:16). It was regarded as the voice of God (Job 37:2; Psalm 18:13; 81:7; comp. John 12:29). In answer to Samuel’s prayer (1 Samuel 12:17,… <em>[Reviewer: condense Easton's entry as needed.]</em>",
