        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>HABERGEON</strong> an Old English word for breastplate. In Job 41:26 (Hebrews shiryah) it is properly a “coat of mail;” the Revised Version has “pointed shaft.” In Exodus 28:32, 39:23, it denotes a military garment strongly and thickly woven and covered with mail round the neck and breast. Such linen corselets have been found in Egypt. The word used in these verses is tahra, which is of Egyptian origin. The Revised Version, however, renders it by “coat of mail.” (See ARMOUR.) <em>[Reviewer: condense Easton's entry as needed.]</em>",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
